    def Prime(self, Volume: int, Mode: int, *, metadata: MetadataDict) -> Prime_Responses:
        self._require_connected()
        if Volume < 10 or Volume > 100000:
            raise InstrumentError(f"Volume must be 10-100000 (1/10 µL), got {Volume}")
        if Mode < 0 or Mode > 3:
            raise InstrumentError(f"Mode must be 0-3, got {Mode}")
        logger.info("Prime: volume=%d, mode=%d", Volume, Mode,
                     extra={"category": "command", "command_name": "Prime"})

        if self._simulation_mode:
            time.sleep(0.5)
            self._sim_primed = True
        else:
            timeout = COMMAND_TIMEOUTS["PRI"] + Volume * VOLUME_TIMEOUT_SCALE
            # Mode is optional: omit for standard prime (mode=0 means "stop continuous",
            # NOT "prime this volume"). Only include mode for continuous/calibration.
            if Mode == 0:
                self._send_command(f"PRI {Volume}", timeout=timeout)
            else:
                self._send_command(f"PRI {Volume} {Mode}", timeout=timeout)
            self._sim_primed = True

        self.update_IsPrimed(True)
        self._push_device_status(f"Primed (volume={Volume}, mode={Mode})")
        return Prime_Responses()

