    def Restart(self, *, metadata: MetadataDict) -> Restart_Responses:
        logger.info("Restart")

        if self._simulation_mode:
            self._sim_connected = False
            self._sim_primed = False
            time.sleep(0.5)
        else:
            # Try to send RST even if not connected — the instrument may be
            # persisting a stale remote-control session and needs a reboot
            # before it will accept a new VER.
            if self._transport.is_connected:
                try:
                    self._send_command("RST", timeout=COMMAND_TIMEOUTS["RST"])
                except Exception:
                    logger.warning("RST command failed, closing port anyway")
            try:
                self._transport._serial.close()
            except Exception:
                pass
            self._transport._serial = None
            self._sim_primed = False

        # Push observable updates
        self.update_IsConnected(False)
        self.update_IsPrimed(False)
        self.update_InstrumentName("")
        self.update_FirmwareVersion("")
        self._push_device_status("Instrument restarted — reconnect required")
        return Restart_Responses()

