    def Dispense(
        self,
        *,
        metadata: MetadataDict,
        instance: ObservableCommandInstanceWithIntermediateResponses[Dispense_IntermediateResponses],
    ) -> Dispense_Responses:
        self._require_connected()
        if not self._sim_primed:
            raise InstrumentError("Must prime before dispensing")
        logger.info("Dispense: simulation=%s", self._simulation_mode,
                     extra={"category": "command", "command_name": "Dispense"})

        instance.begin_execution()
        self._push_device_status("Dispensing...")

        if self._simulation_mode:
            result = self._dispense_simulated(instance)
        else:
            result = self._dispense_real(instance)

        self._push_device_status("Dispense completed")
        return result

    def _dispense_simulated(
        self,
        instance: ObservableCommandInstanceWithIntermediateResponses[Dispense_IntermediateResponses],
    ) -> Dispense_Responses:
        total_columns = 12
        total_rows = 8
        total_steps = total_columns * total_rows

        instance.estimated_remaining_time = timedelta(seconds=total_steps * 0.1)
        step = 0

        for col in range(1, total_columns + 1):
            for row in range(1, total_rows + 1):
                step += 1
                progress = step / total_steps
                instance.progress = progress
                instance.estimated_remaining_time = timedelta(
                    seconds=(total_steps - step) * 0.1
                )
                instance.send_intermediate_response(
                    Dispense_IntermediateResponses(ColumnRow=f"Col {col} Row {row}")
                )
                time.sleep(0.1)

        logger.info("Dispense completed (simulation)")
        return Dispense_Responses(Status="Dispense completed successfully")

    def _dispense_real(
        self,
        instance: ObservableCommandInstanceWithIntermediateResponses[Dispense_IntermediateResponses],
    ) -> Dispense_Responses:
        try:
            for line in self._transport.send_command_streaming("DIS"):
                instance.send_intermediate_response(
                    Dispense_IntermediateResponses(ColumnRow=line)
                )
        except ConnectionError as e:
            logger.error("Dispense communication error: %s", e)
            raise CommunicationError(str(e))
        except RuntimeError as e:
            logger.error("Dispense instrument error: %s", e)
            raise InstrumentError(str(e))
        except Exception as e:
            logger.error("Dispense failed: %s", e)
            raise CommunicationError(f"Dispense failed: {e}")

        logger.info("Dispense completed (real)")
        return Dispense_Responses(Status="Dispense completed successfully")

    def Shake(
        self,
        Time: int,
        Distance: int,
        Speed: int,
        *,
        metadata: MetadataDict,
        instance: ObservableCommandInstance,
    ) -> Shake_Responses:
        self._require_connected()
        if Time < 1:
            raise InstrumentError(f"Shake time must be >= 1 (1/100 s), got {Time}")
        if Distance < 1 or Distance > 5:
            raise InstrumentError(f"Shake distance must be 1-5 mm, got {Distance}")
        if Speed < 1 or Speed > 20:
            raise InstrumentError(f"Shake speed must be 1-20 Hz, got {Speed}")
        # Validate distance/speed combination per manual Table 3-2
        max_dist_for_speed = {9:4, 10:3, 11:3, 12:2, 13:2, 14:2, 15:1, 16:1, 17:1, 18:1, 19:1, 20:1}
        max_dist = max_dist_for_speed.get(Speed, 5)
        if Distance > max_dist:
            raise InstrumentError(f"Distance {Distance} mm too high for speed {Speed} Hz (max {max_dist} mm)")
        logger.info("Shake: time=%d, distance=%d, speed=%d", Time, Distance, Speed)

        instance.begin_execution()
        self._push_device_status(f"Shaking (time={Time}, dist={Distance}, speed={Speed})...")

        if self._simulation_mode:
            shake_seconds = Time / 100.0
            instance.estimated_remaining_time = timedelta(seconds=shake_seconds)

            UPDATE_INTERVAL = 0.2
            elapsed = 0.0
            while elapsed < shake_seconds:
                time.sleep(min(UPDATE_INTERVAL, shake_seconds - elapsed))
                elapsed += UPDATE_INTERVAL
                progress = min(1.0, elapsed / shake_seconds)
                instance.progress = progress
                remaining = max(0, shake_seconds - elapsed)
                instance.estimated_remaining_time = timedelta(seconds=remaining)

            logger.info("Shake completed (simulation)")
        else:
            timeout = COMMAND_TIMEOUTS["SHA"] + (Time / 100.0)
            self._send_command(f"SHA {Time} {Distance} {Speed}", timeout=timeout)
            logger.info("Shake completed (real)")

        self._push_device_status("Shake completed")
        return Shake_Responses()
